css:
.tn-root{position:absolute;left:50%;bottom:64px;transform:translateX(-50%);display:flex;align-items:stretch;font-family:var(--tn-font);background:linear-gradient(180deg,rgba(16,16,16,.96),rgba(12,12,12,.9));border:1px solid #2e2e2e;border-top:3px solid var(--tn-accent);border-radius:8px;overflow:hidden;box-shadow:0 6px 20px rgba(0,0,0,.35);}
.tn-card{display:flex;align-items:center;gap:16px;padding:14px 32px;min-width:310px;}
.tn-avatar{width:var(--tn-avatar-size);height:var(--tn-avatar-size);flex:0 0 auto;overflow:hidden;background:#0d0d0d;border:1px solid rgba(255,255,255,.18);border-radius:50%;display:flex;align-items:center;justify-content:center;}
.tn-avatar img{width:100%;height:100%;object-fit:cover;display:none;}
.tn-avatar img.is-ready{display:block;}
.tn-fallback{color:#6a6a6a;font-size:28px;font-weight:700;}
.tn-avatar:has(img.is-ready) .tn-fallback{display:none;}
.tn-meta{display:flex;flex-direction:column;gap:3px;min-width:0;}
.tn-role{display:flex;align-items:center;gap:8px;font-size:var(--tn-role-size);font-weight:600;letter-spacing:2.5px;line-height:1;color:var(--tn-accent);}
.tn-role:before{content:'';width:14px;height:2px;background:var(--tn-accent);flex:0 0 auto;}
.tn-role:empty{display:none;}
.tn-name{font-size:var(--tn-name-size);font-weight:700;color:#f2f2f2;line-height:1.2;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.tn-sep{width:1px;background:#333;margin:10px 0;flex:0 0 auto;}
